let url = 'https://coolors.co/fca824-ffe69b';
let palette = url.split('/')[3].split('-').map(c => '#' + c);
let vmin, vmax;
let gl, glsl;

function preload() {
  glsl = loadShader('https://openprocessing.org/sketch/1519159/files/shader.vert', 'shader.frag');
}

function setup() {
  createCanvas(1112, 834, WEBGL);
  noStroke();
  gl = drawingContext;
  vmin = max(width, height);
  vmax = max(width, height);
  camera(vmin * 0.5, -vmin * 0.1, vmin * 0.35)
}

function spherical(radius, theta, phi, thetaOffset, phiOffset, detailX, detailY) {
  let gId = `spherical|${theta}|${phi}|${thetaOffset}|${phiOffset}|${detailX}|${detailY}`;
  if (!this._renderer.geometryInHash(gId)) {
    let cb = function(detailX, detailY) {
      let u, v, p;
      for (let i = 0; i <= this.detailY; i++) {
        v = i / this.detailY;
        for (let j = 0; j <= this.detailX; j++) {
          u = j / this.detailX;
          p = new p5.Vector(u - 0.5, v - 0.5, 0);
          let t = u * theta + thetaOffset;
          let f = v * phi + phiOffset;
          let r = 1;
          p.x = sin(t) * cos(f) * r;
          p.y = sin(f) * r;
          p.z = cos(t) * cos(f) * r; 
          this.vertices.push(p);
          this.vertexNormals.push(p);
          this.uvs.push(u, v);
        }
      }
    };
    let geom = new p5.Geometry(detailX, detailY, cb);
    geom.computeFaces().computeNormals();
    this._renderer.createBuffers(gId, geom);
  }
  this._renderer.drawBuffersScaled(gId, radius, radius, radius);
}

function draw() {
  let sec = millis() / 1000;
  let radius = vmin * 0.3;
  let theta = TWO_PI;
  let phi = PI * 0.5;
  let thetaOffset = 0;
  let phiOffset = -phi;
  let detailX = 32;
  let detailY = 32;
  background(0);
	push();
	translate(0,76,0);
	fill(155,0,0);
	rotateY(1);
	ellipsoid(246,5,246);
	pop();
  gl.enable(gl.DEPTH_TEST);
  gl.depthFunc(gl.ALWAYS);
  gl.enable(gl.BLEND);
  gl.blendFunc(gl.SRC_ALPHA, gl.ONE);

  push();
  {
    translate(0, radius * 0.3, 0);
    shader(glsl);
    glsl.setUniform('PI', PI);
    glsl.setUniform('uTime', sec);
    glsl.setUniform('uColor0', color(palette[0])._array);
    glsl.setUniform('uColor1', color(palette[1])._array);
    spherical(radius * 0.97, theta, phi, thetaOffset, phiOffset, detailX, detailY);

    glsl.setUniform('uTime', sec + 123.456);
    rotateY(-sec * 0.75);
    spherical(radius, theta, phi, thetaOffset, phiOffset, detailX, detailY);
  }
  pop();
}

